import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.jwovEGr5.js";const s="/assets/treasure_radar.D5ACjL-1.png",n="/assets/leaderboard_gui.DxN3gPVW.png",g=JSON.parse('{"title":"⚔️ 每日任務與全服懸賞系統指南","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-Task-System.md","filePath":"Mc-Task-System.md"}'),l={name:"Mc-Task-System.md"};function i(c,a,d,h,p,u){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="⚔️-每日任務與全服懸賞系統指南" tabindex="-1">⚔️ 每日任務與全服懸賞系統指南 <a class="header-anchor" href="#⚔️-每日任務與全服懸賞系統指南" aria-label="Permalink to &quot;⚔️ 每日任務與全服懸賞系統指南&quot;">​</a></h1><p>遊戲內提供了豐富的每日任務與全服懸賞目標，完成任務是獲取金幣與抽獎鑰匙的重要管道！</p><p><img src="'+s+'" alt="任務與懸賞選單"></p><hr><h2 id="📅-1-任務類型與更新" tabindex="-1">📅 1. 任務類型與更新 <a class="header-anchor" href="#📅-1-任務類型與更新" aria-label="Permalink to &quot;📅 1. 任務類型與更新&quot;">​</a></h2><p>每日任務在每天凌晨 0:00 自動更新，每人每日隨機分配：</p><ul><li><strong>擊殺任務</strong>：指定擊殺一定數量的怪物（如 15 隻殭屍）。</li><li><strong>挖掘任務</strong>：指定挖掘一定數量的礦石或方塊（如 20 個煤礦石）。 <ul><li><em>連鎖挖礦支援</em>：使用連鎖挖礦一次性打破多個目標礦物，也會 100% 正確計入每日任務進度！</li></ul></li></ul><hr><h2 id="📈-2-查詢任務進度" tabindex="-1">📈 2. 查詢任務進度 <a class="header-anchor" href="#📈-2-查詢任務進度" aria-label="Permalink to &quot;📈 2. 查詢任務進度&quot;">​</a></h2><p>在遊戲內，您可以輸入指令或在 <code>/menu</code> 選單中查看：</p><ul><li><strong><code>/task</code></strong>：在聊天欄顯示今日任務的具體目標、您目前的進度與完成狀態。</li><li><strong>即時提示</strong>：每當您擊殺指定怪物或挖掘指定方塊時，聊天欄都會即時顯示當前進度。</li></ul><hr><h2 id="🎁-3-即時自動領取獎勵" tabindex="-1">🎁 3. 即時自動領取獎勵 <a class="header-anchor" href="#🎁-3-即時自動領取獎勵" aria-label="Permalink to &quot;🎁 3. 即時自動領取獎勵&quot;">​</a></h2><ul><li><strong>達標即時發放</strong>：當任務進度達到 100% 時，系統會播放音效並<strong>自動即時發放獎勵</strong>（金幣/鑰匙/物品）至您的背包與個人帳戶中，無需任何手動領取動作！</li></ul><hr><h2 id="🏆-全服排行榜系統" tabindex="-1">🏆 全服排行榜系統 <a class="header-anchor" href="#🏆-全服排行榜系統" aria-label="Permalink to &quot;🏆 全服排行榜系統&quot;">​</a></h2><p>玩家可以在 <code>/menu -&gt; 🏆 全服排行榜</code> 中隨時查看全服 <strong>💰 財富 Top 10</strong>、<strong>🔑 鑰匙 Top 10</strong> 與 <strong>📅 連續簽到 Top 10</strong>，榜單會實時渲染玩家皮膚頭像！</p><p><img src="'+n+'" alt="全服排行榜"></p>',18)])])}const m=t(l,[["render",i]]);export{g as __pageData,m as default};
